\title{A Formal Toolkit for Monotone Circuit Lower Bounds:\\
Relevant Variables, the Approximation Method,\\ and Karchmer--Wigderson}
\author{Aristotle}
\date{2026-06-28}

\begin{document}
\maketitle

\begin{abstract}
We develop a self-contained mathematical framework for proving lower bounds on the
complexity of \emph{monotone Boolean circuits} --- circuits built from AND and OR
gates with no negation. We formalize monotone circuits over an arbitrary index type
of input variables, together with their evaluation, size, depth, and the set of
variables they read. On this foundation we prove three complementary lower-bound
techniques. First, the \emph{relevant-variable bound}: the size of a circuit is at
least the number of input variables that genuinely influence the function it
computes; we instantiate this to show that any monotone circuit computing the
$2$-CLIQUE function on $m$ vertices has size at least $\binom{m}{2}$. Second, the
abstract engine of \emph{Razborov's approximation method}: modeling gate-wise
approximation by an arbitrary rounding operator, we prove that approximation error
accumulates \emph{linearly} in the number of gates, and derive the conditional size
lower bound $\size \ge E/\delta$ relating global far-ness $E$ to per-gate error
$\delta$. Third, the constructive half of the \emph{Karchmer--Wigderson
correspondence}: a depth-$d$ monotone circuit yields a $d$-bit communication
protocol that solves the monotone Karchmer--Wigderson relation. All results are
established by structural induction and elementary finite combinatorics.
\end{abstract}

\section{Introduction}
Proving that explicit Boolean functions require large circuits is among the central
goals of complexity theory and remains largely out of reach for general
(non-monotone) circuits. The \textbf{monotone} restriction --- circuits using only
AND and OR gates --- is a rare success story: here we possess techniques powerful
enough to prove \emph{exponential} lower bounds for natural functions such as CLIQUE
(Razborov, 1985), and a clean correspondence between circuit depth and communication
complexity (Karchmer--Wigderson, 1988).

This paper assembles a compact, rigorous toolkit covering the three pillars of
monotone lower-bound theory: the relevant-variable method
(Sections~\ref{sec:vars}--\ref{sec:clique}), the approximation method
(Section~\ref{sec:approx}), and the Karchmer--Wigderson connection
(Section~\ref{sec:kw}). Our contribution is to isolate the \emph{structural core} of
each technique --- the part provable cleanly and independently of any particular hard
function --- and to state each result generically so that problem-specific
combinatorial estimates plug directly into a proven scaffold.

\section{Monotone circuits}
Throughout, let $\iota$ be an arbitrary type of variable indices.

\begin{definition}[Monotone circuit]
The type $\mathrm{MCircuit}(\iota)$ is generated inductively by: $\vVar\,i$ for
$i:\iota$; the constants $\top$ and $\bot$; and $\vAnd\,a\,b$, $\vOr\,a\,b$ for
subcircuits $a,b$.
\end{definition}

\begin{definition}[Evaluation]
For $x:\iota\to\mathrm{Bool}$,
\[
\eval(\vVar\,i)\,x = x_i,\quad \eval\,\top\,x=\true,\quad \eval\,\bot\,x=\false,
\]
\[
\eval(\vAnd\,a\,b)\,x = \eval\,a\,x \wedge \eval\,b\,x,\qquad
\eval(\vOr\,a\,b)\,x = \eval\,a\,x \vee \eval\,b\,x.
\]
\end{definition}

\begin{definition}[Size, depth, variables]
$\size$ of a leaf is $1$ and of a gate is $\size\,a + \size\,b + 1$. $\depth$ of a
leaf is $0$ and of a gate is $\max(\depth\,a,\depth\,b)+1$. For decidable $\iota$,
$\vars(\vVar\,i)=\{i\}$, $\vars\,\top=\vars\,\bot=\emptyset$, and
$\vars(\vAnd\,a\,b)=\vars(\vOr\,a\,b)=\vars\,a\cup\vars\,b$.
\end{definition}

\begin{theorem}[Monotonicity, \texttt{eval\_monotone}]
For every $C$ and assignments $x,y$ with $x_i=\true\Rightarrow y_i=\true$ for all
$i$, we have $\eval\,C\,x=\true \Rightarrow \eval\,C\,y=\true$.
\end{theorem}
\begin{proof}[Proof sketch]
Induction on $C$. Variables and constants are immediate. For $\vAnd\,a\,b$, a true
output means both children are true on $x$; by induction both are true on $y$, hence
so is the AND. The $\vOr$ case is symmetric.
\end{proof}

\section{Relevant variables}\label{sec:vars}

\begin{lemma}[Locality, \texttt{eval\_eq\_of\_agree\_on\_vars}]
If $x_i=y_i$ for all $i\in\vars\,C$, then $\eval\,C\,x=\eval\,C\,y$.
\end{lemma}
\begin{proof}[Proof sketch]
Induction on $C$. At $\vVar\,i$, agreement on $\{i\}$ gives $x_i=y_i$. At a gate, the
variable set is the union of the children's, so agreement restricts to each child and
the inductive hypotheses combine.
\end{proof}

\begin{definition}[Relevant variable, \texttt{DependsOn}]
A variable $i$ is \emph{relevant} to $f:(\iota\to\mathrm{Bool})\to\mathrm{Bool}$ if
there is an assignment $x$ with $f(x[i\mapsto\true])\neq f(x[i\mapsto\false])$.
\end{definition}

\begin{theorem}[Relevance forces occurrence, \texttt{dependsOn\_mem\_vars}]
If $i$ is relevant to $\eval\,C$, then $i\in\vars\,C$.
\end{theorem}
\begin{proof}[Proof sketch]
Contrapositive. If $i\notin\vars\,C$, then for any $x$ the assignments
$x[i\mapsto\true]$ and $x[i\mapsto\false]$ agree on $\vars\,C$; by locality $C$ gives
the same value on both, contradicting relevance.
\end{proof}

\begin{theorem}[Variable count bounds size, \texttt{card\_vars\_le\_size}]
For every $C$, $|\vars\,C|\le\size\,C$.
\end{theorem}
\begin{proof}[Proof sketch]
Induction; a variable contributes $1$, constants $0$, and at a gate
$|\vars\,a\cup\vars\,b|\le|\vars\,a|+|\vars\,b|\le\size\,a+\size\,b\le\size\,C$.
\end{proof}

\begin{theorem}[Relevant-variable lower bound, \texttt{card\_le\_size\_of\_relevant}]
If $R$ is a finite set of variables each relevant to $\eval\,C$, then
$|R|\le\size\,C$.
\end{theorem}
\begin{proof}[Proof sketch]
Each $i\in R$ lies in $\vars\,C$, so $R\subseteq\vars\,C$ and
$|R|\le|\vars\,C|\le\size\,C$.
\end{proof}

\section{CLIQUE and a quadratic bound}\label{sec:clique}
Model a graph on $\Fin\,m$ by its edge indicator $g:\Symtwo(\Fin\,m)\to\mathrm{Bool}$.

\begin{definition}[CLIQUE function, \texttt{cliqueFn}]
\[
\cliqueFn(m,k,g) = \big[\,\exists S\subseteq\Fin\,m,\ |S|=k \wedge
\forall u,v\in S,\ u\neq v\Rightarrow g(\{u,v\})=\true\,\big].
\]
\end{definition}

\begin{theorem}[Monotonicity, \texttt{cliqueFn\_monotone}]
If $g(e)=\true\Rightarrow g'(e)=\true$ for all $e$, then
$\cliqueFn(m,k,g)=\true\Rightarrow\cliqueFn(m,k,g')=\true$.
\end{theorem}
\begin{proof}[Proof sketch]
A witnessing clique $S$ of $g$ has all internal edges in $g$, hence in $g'$, so $S$
witnesses a clique of $g'$.
\end{proof}

\begin{theorem}[Edge relevance for $k=2$, \texttt{cliqueFn\_two\_dependsOn}]
Every non-loop edge $e$ is relevant to $\cliqueFn(m,2)$.
\end{theorem}
\begin{proof}[Proof sketch]
From the empty graph: with $e$ off there is no $2$-clique (false); with
$e=\{a,b\}$ on ($a\neq b$), $\{a,b\}$ is a $2$-clique (true).
\end{proof}

\begin{lemma}[Edge count, \texttt{card\_offDiag\_eq\_choose}]
The number of non-loop edges on $\Fin\,m$ equals $\binom{m}{2}$.
\end{lemma}

\begin{theorem}[Quadratic lower bound, \texttt{clique2\_size\_ge\_choose}]
Any monotone circuit $C$ with $\eval\,C\,g=\cliqueFn(m,2,g)$ for all $g$ satisfies
$\size\,C\ge\binom{m}{2}$.
\end{theorem}
\begin{proof}[Proof sketch]
The $\binom{m}{2}$ non-loop edges are all relevant; apply the relevant-variable
lower bound.
\end{proof}

\section{The approximation method}\label{sec:approx}

\begin{definition}[Internal gate count, \texttt{numGates}]
$\numGates$ of a leaf is $0$ and of a gate is $\numGates\,a+\numGates\,b+1$.
\end{definition}

\begin{lemma}[\texttt{numGates\_le\_size}]
$\numGates\,C\le\size\,C$.
\end{lemma}

\begin{definition}[Approximate evaluation, \texttt{approxEval}]
Given a rounding operator $R$ on Boolean functions, $\approxEval\,R$ is defined as
$\eval$ except that $R$ is applied to the function computed at each gate:
\[
\approxEval\,R\,(\vAnd\,a\,b)\,x = R\big(z\mapsto \approxEval\,R\,a\,z\wedge
\approxEval\,R\,b\,z\big)(x),
\]
and analogously for $\vOr$. Taking $R=\mathrm{id}$ recovers $\eval$.
\end{definition}

\begin{theorem}[Error accumulation, \texttt{approx\_error\_bound}]
Let $R$ be any rounding operator, $T$ a finite test set, and $\delta\in\mathbb{N}$
with $|\{x\in T: R(g)(x)\neq g(x)\}|\le\delta$ for every $g$. Then for every $C$,
\[
\big|\{x\in T: \eval\,C\,x\neq\approxEval\,R\,C\,x\}\big| \le \numGates(C)\cdot\delta.
\]
\end{theorem}
\begin{proof}[Proof sketch]
Induction on $C$. Leaves are evaluated identically, so the error set is empty. For
$\vAnd\,a\,b$, any input on which the true and rounded circuits disagree witnesses a
disagreement in the left child, the right child, or the local rounding step; the
error set is contained in the union of these three. By the union bound its size is at
most $\numGates\,a\cdot\delta + \numGates\,b\cdot\delta + \delta = \numGates(C)\cdot
\delta$. The $\vOr$ case is identical.
\end{proof}

\begin{theorem}[Size lower bound, \texttt{approx\_method\_size\_lb}]
Under the above hypotheses, if additionally
$|\{x\in T:\eval\,C\,x\neq\approxEval\,R\,C\,x\}|\ge E$, then
\[
E \le \numGates(C)\cdot\delta \le \size(C)\cdot\delta,\qquad\text{i.e.}\qquad
\size(C)\ge \frac{E}{\delta}.
\]
\end{theorem}
\begin{proof}[Proof sketch]
Chain far-ness, error accumulation, and $\numGates\le\size$.
\end{proof}

Razborov's argument supplies, for $k$-CLIQUE, a sunflower-based $R$ with $E/\delta$
exponential in a power of $k$, yielding $\size(C)=2^{\Omega(\sqrt{k})}$ via the above.

\section{The Karchmer--Wigderson connection}\label{sec:kw}

\begin{definition}[KW protocol and cost, \texttt{kwFind}, \texttt{kwCost}]
$\kwFind(\vVar\,i)=\mathrm{some}\,i$, $\kwFind\,\top=\kwFind\,\bot=\mathrm{none}$;
at $\vAnd\,a\,b$ descend into $a$ if $\eval\,a\,y=\false$ else into $b$; at
$\vOr\,a\,b$ descend into $a$ if $\eval\,a\,x=\true$ else into $b$. $\kwCost$ follows
the same recursion, counting one bit per gate.
\end{definition}

\begin{theorem}[Correctness, \texttt{kwFind\_spec}]
If $\eval\,C\,x=\true$ and $\eval\,C\,y=\false$, then $\kwFind\,C\,x\,y=\mathrm{some}\,
i$ for some $i$ with $x_i=\true$ and $y_i=\false$.
\end{theorem}
\begin{proof}[Proof sketch]
Induction maintaining ``$\eval\,C\,x=\true$ and $\eval\,C\,y=\false$''. Constants are
excluded; at $\vVar\,i$ the invariant gives the answer; at a gate the routing
preserves the invariant for the chosen child.
\end{proof}

\begin{theorem}[Depth bounds communication, \texttt{kwCost\_le\_depth}]
For all $x,y$, $\kwCost\,C\,x\,y\le\depth\,C$.
\end{theorem}
\begin{proof}[Proof sketch]
At a gate the cost is $1+(\text{cost of one child})\le 1+\max(\depth\,a,\depth\,b)$.
\end{proof}

\begin{corollary}[Monotone separator, \texttt{monotone\_separator\_exists}]
If $\eval\,C\,x=\true$ and $\eval\,C\,y=\false$, there is $i$ with $x_i=\true$ and
$y_i=\false$.
\end{corollary}

\section{Discussion and future work}
The relevant-variable bound is exact but polynomial; the approximation method breaks
this barrier by tracking errors rather than variables, with a fully general
structural core; the Karchmer--Wigderson connection reduces depth lower bounds to
communication lower bounds.

\begin{conjecture}[Sunflower instantiation]
There is a sunflower-based rounding operator $R$, test set $T$, and budgets
$\delta, E$ with $E/\delta$ exponential in $m$ satisfying the size-lower-bound
hypotheses for any monotone circuit computing $\cliqueFn(m,k)$, giving size
$2^{\Omega(\sqrt{k})}$.
\end{conjecture}

\begin{conjecture}[Converse Karchmer--Wigderson]
Every cost-$c$ protocol for the monotone KW relation of $f$ compiles into a monotone
circuit of depth $\le c$ computing $f$, making monotone depth equal to monotone KW
communication complexity.
\end{conjecture}

\begin{conjecture}[Tightness]
Characterize when the relevant-variable bound is an equality --- conjecturally for
read-once-like circuits with disjoint variable sets at each gate.
\end{conjecture}

