    if C = var i:        return x[i]
    if C = top:          return true
    if C = bot:          return false
    if C = and(a, b):
        g := (z -> approxEval(R,a,z) AND approxEval(R,b,z))
        return R(g)(x)
    if C = or(a, b):
        g := (z -> approxEval(R,a,z) OR approxEval(R,b,z))
        return R(g)(x)

function approximationLowerBound(C, R, T, delta):
    E := count of x in T with eval(C,x) != approxEval(R,C,x)
    assert E <= numGates(C) * delta        # error-accumulation invariant
    return E / delta                        # certified: size(C) >= E/delta

