function kwFind(C, x, y):           # precondition eval(C,x)=true, eval(C,y)=false
    if C = var i:   return i
    if C = and(a,b):
        if eval(a,y) = false: return kwFind(a, x, y)   # Bob sends 1 bit
        else:                 return kwFind(b, x, y)
    if C = or(a,b):
        if eval(a,x) = true:  return kwFind(a, x, y)   # Alice sends 1 bit
        else:                 return kwFind(b, x, y)

function kwCost(C, x, y):
    if C is a leaf: return 0
    pick child as in kwFind
    return 1 + kwCost(child, x, y)      # guaranteed kwCost <= depth(C)

